  "hechos": [
    {
      "id": "H1",
      "texto": "El servicio de urgencias del Hospital San Rafael, en Altamira del Río, dejó de atender.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4", "P5"]
    },
    {
      "id": "H2",
      "texto": "El hospital atendía unas 120 urgencias al día.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4", "P5"]
    },
    {
      "id": "H3",
      "texto": "Los pacientes están siendo remitidos al hospital de Santa Brígida, a 50 kilómetros.",
      "tipo": "dato",
      "paginas": ["P1", "P3", "P5"]
    },
    {
      "id": "H4",
      "texto": "El cierre se debe a que no hay médicos suficientes para cubrir los turnos.",
      "tipo": "dato",
      "paginas": ["P2", "P3", "P4"]
    },
    {
      "id": "H5",
      "texto": "Gloria Mejía, líder comunal del barrio Santa Rita, contó a El Faro Regional que las farmacias del pueblo están recibiendo más consultas.",
      "tipo": "atribucion",
      "paginas": ["P4"]
    },
    {
      "id": "H6",
      "texto": "En el barrio Las Acacias, la junta de acción comunal contó 128 personas remitidas a otro municipio esta semana.",
      "tipo": "atribucion",
      "paginas": ["P3"]
    },
    {
      "id": "H7",
      "texto": "En el barrio Primero de Mayo, la junta de acción comunal contó 457 personas remitidas a otro municipio esta semana.",
      "tipo": "atribucion",
      "paginas": ["P4"]
    },
    {
      "id": "H8",
      "texto": "En el barrio La Pradera, la junta de acción comunal contó 50 personas remitidas a otro municipio esta semana.",
      "tipo": "atribucion",
      "paginas": ["P5"]
    }
  ]
}
